{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.hyuman_unicommerce_fact_items as SELECT null AS customer_id, shipping_address_pincode AS pincode, channel_name AS marketplace, channel_name AS source, display_order_code AS order_id, display_order_code AS reference_code, Notification_Mobile AS phone, Billing_Address_Name AS name, cast(null AS string) AS email, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(updated, \'\')))) AS SHIPPING_LAST_UPDATE_DATE, item_sku_code AS sku, Seller_SKU_Code AS Marketplace_sku, CASE WHEN REGEXP_CONTAINS(channel_product_id, r\'^\d+-\d+$\') THEN SPLIT(channel_product_id, \'-\')[OFFSET(0)] ELSE channel_product_id END AS product_id, CASE WHEN REGEXP_CONTAINS(channel_product_id, r\'^\d+-\d+$\') THEN SPLIT(channel_product_id, \'-\')[OFFSET(1)] ELSE NULL END AS variant_id, item_type_name AS product_name, currency, coalesce(shipping_address_city, Billing_Address_City) city, coalesce(shipping_address_state, Billing_Address_state) state, sale_order_status AS order_status, invoice_code, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(invoice_created, \'\')))) AS invoiceDate, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(Order_Date_as_dd_mm_yyyy_hh_MM_ss, \'\')))) AS Order_Date, SAFE_CAST(Shipping_Charges AS FLOAT64) AS shipping_price, 1 AS suborder_quantity, SAFE_CAST(discount AS FLOAT64) AS discount, SAFE_CAST(tax_value AS FLOAT64) AS tax, SAFE_CAST(selling_price AS FLOAT64) AS selling_price, Shipping_Package_Code AS shippingPackageCode, Shipping_Package_Status_Code AS shippingPackageStatus, Sale_Order_Item_Code AS SaleOrderItemCode, Sale_Order_Item_Code AS Sales_Order_Item_ID, Tracking_Number AS AWB, Facility AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, Shipping_Courier AS Courier, Shipping_Courier_Status AS shipping_status, 1 AS shippedQuantity, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(Dispatch_Date, \'\')))) AS Dispatch_Date, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(Delivery_Time, \'\')))) AS Delivered_Date, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(return_date, \'\')))) AS return_date, return_remarks, Reverse_Pickup_Reason, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN CAST(selling_price AS FLOAT64) ELSE 0 END AS return_sales, CASE WHEN lower(sale_order_status) LIKE \'%cancel%\' OR lower(shipping_courier_status) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, cast(null AS string) AS new_customer_flag, cast(null AS string) AS acquisition_product, null AS days_in_shipment, null AS acquisition_date, cast(item_sku_code as string) AS SKU_CODE, case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_name) else UPPER(p.PRODUCT_name) end AS PRODUCT_NAME_Final, p.product_sub_category, case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_code) else UPPER(p.commonsku) end AS commonsku, p.color_sku, p.parent_sku, p.image_url, p.mrp, case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.category_name) else upper(p.category) end AS Product_category, coalesce(pmt.type,pm.type) as type, case when upper(channel_name) like \'%MEESHO%\' then 55 when upper(channel_name) like \'%FLIPKART%\' then ifnull(src.shipping_rate,0) end as shipping_rate from `maplemonk.hyuman_Unicommerce_main_get_sale_orders` fi LEFT JOIN ( SELECT product_code AS commonsku, cast(null as string) as color_sku, product_code as parent_sku, PRODUCT_name, category, CAST(NULL AS STRING) AS product_sub_category, CAST(NULL AS STRING) AS image_url, MRP FROM `hyuman-wh.maplemonk.Final_sku_master` ) p ON LOWER(fi.item_sku_code) = LOWER(p.commonsku) left join (select product_code, type from ( select product_code, type, row_number() over (partition by product_code order by 1) rw from hyuman-wh.maplemonk.unicommerce_myhyuman_get_product_master ) where rw = 1) pm on lower(pm.product_Code) = lower(fi.Seller_SKU_Code) or lower(pm.product_Code) = lower(fi.item_sku_code) left join (select * from ( select product_code, type, name as product_name, Brand, category_name, row_number() over (partition by product_code order by 1) rw from hyuman-wh.maplemonk.unicommerce_myhyuman_get_product_master ) where rw = 1 ) pmt on upper(pmt.product_code) = upper(fi.Seller_SKU_Code) or upper(pmt.product_code) = upper(fi.Seller_SKU_Code) LEFT JOIN (SELECT * FROM ( SELECT upper(trim(Master_SKU_Code)) AS commonsku, upper(trim(Flipkart_SKU_Code)) as fk_sku, cast(shipping_rate as float64) as shipping_rate, ROW_NUMBER() OVER (PARTITION BY upper(trim(Master_SKU_Code)) ORDER BY LENGTH(COALESCE(Master_SKU_Code,\'\')) DESC) rw FROM `MapleMonk.GS_Flipkart_Shipping_Rate_Card` ) WHERE rw = 1 ) src ON LOWER(case when upper(pmt.type) = \'BUNDLE\' then upper(pmt.product_code) else UPPER(p.commonsku) end) = LOWER(src.fk_sku) qualify row_number() over (partition by display_order_code,Sale_Order_Item_Code order by FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', updated)) desc) = 1 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            